const existing=$input.all().map(i=>i.json).find(r=>r.opportunity_id && String(r.owner_id)===req.owner_id && r.dedupe_key===req.dedupe_key);
return [{json:{...req,exists:!!existing,existing_title:existing?.title||'',existing_id:existing?.opportunity_id||''}}];

const req = $('Check Existing').first().json;

const res = $input.first().json || {};

const status = Number(
  res.statusCode || (res.error ? 500 : 200)
);

const body = String(res.data || res.body || '');

const MAX_EXTRA = 2;


// NORMALIZE SOURCE LINKS

function parseLink(raw, origin = '') {

  let s = String(raw || '')
    .trim()
    .split('#')[0];

  // Support root-relative links
  if (
    s.startsWith('/') &&
    !s.startsWith('//') &&
    origin
  ) {
    s = origin + s;
  }

  if (
    s.length > 1500 ||
    /[\s\\]/.test(s)
  ) return null;

  const m = s.match(
    /^(https?):\/\/([a-z0-9.-]+)(\/[^?]*)?(\?.*)?$/i
  );

  if (!m) return null;

  const host = m[2].toLowerCase();

  const base =
    m[1].toLowerCase() + '://' + host;

  const path = m[3] || '/';

  const query = (m[4] || '')
    .slice(1)
    .split('&')
    .filter(p =>
      p &&
      !/^(utm_[^=]*|gclid|fbclid)(=|$)/i.test(p)
    )
    .join('&');

  const tail = query ? '?' + query : '';

  return {
    host,
    base,
    path,

    url: base + path + tail,

    key:
      host +
      (path.replace(/\/+$/, '') || '/') +
      tail
  };

}


// SCORE SOURCE RELEVANCE

function rank(label, link) {

  const s = (label + ' ' + link.path)
    .toLowerCase()
    .replace(/[-_]/g, ' ');

  // Ignore unrelated navigation

  if (
    /privacy|cookie|sign in|log in|newsletter|donate|unsubscribe/
      .test(s)
  ) return null;


  // Eligibility and requirements

  if (
    /guide for applicants|applicant guide|eligib|official rules|requirements|application guide|guidelines|terms and conditions|criteria/
      .test(s)
  ) {
    return {
      role: 'rules',
      score: 100
    };
  }


  // Application forms

  if (
    /proposal form|application form|apply now|\bsubmit\b|\bpropose\b|how to apply|\bapply\b/
      .test(s)
  ) {
    return {
      role: 'form',
      score: 95
    };
  }


  // Policies and restrictions

  if (
    /\brules\b|\bterms\b|ai policy|funding policy|conditions|restrictions/
      .test(s)
  ) {
    return {
      role: 'rules',
      score: 85
    };
  }


  // Important dates and schedules

  if (
    /\bschedule\b|\bdates\b|deadline/.test(s)
  ) {
    return {
      role: 'dates',
      score: 90
    };
  }


  // Supporting information

  if (
    /faq|frequently asked|prize|application|funding guide/
      .test(s)
  ) {
    return {
      role: 'details',
      score: 65
    };
  }

  return null;

}


// PRESERVE OPPORTUNITY CONTEXT

const arr = [{
  source_id: 'S1',
  url: req.url,
  chat_id: req.chat_id,
  owner_id: req.owner_id,
  opportunity_id: req.opportunity_id,
  dedupe_key: req.dedupe_key
}];

const warnings = [];

const initial = parseLink(req.url);

const candidates = new Map();

const outside = new Set();


const readable =
  status >= 200 &&
  status < 300 &&
  body.length >= 240 &&
  !/^\s*(?:error:|403 forbidden)/i.test(body);


// ADD AND DEDUPLICATE CANDIDATES

function addCandidate(link, r) {

  if (
    !link ||
    !r ||
    link.key === initial.key
  ) return;

  if (link.host !== initial.host) {

    outside.add(link.key);

    return;
  }

  const old = candidates.get(link.key);

  if (!old || r.score > old.score) {

    candidates.set(link.key, {
      ...link,
      ...r
    });

  }

}


// DISCOVER SOURCES

if (initial && readable) {


  // GENERAL LINK DISCOVERY

  const links =
    /\[([^\]]{1,180})\]\((https?:\/\/[^\s)]+|\/(?!\/)[^\s)]*)\)/gi;

  for (const m of body.matchAll(links)) {

    // Ignore images
    if (
      m.index > 0 &&
      body[m.index - 1] === '!'
    ) continue;

    const link = parseLink(
      m[2],
      initial.base
    );

    if (link) {

      addCandidate(
        link,
        rank(m[1], link)
      );

    }

  }


  // PLATFORM DETECTION

  const eventHost =
    /^[a-z0-9-]+\.devpost\.com$/
      .test(initial.host) &&

    !/^(www|help|info|secure|api|blog|status|support)\.devpost\.com$/
      .test(initial.host);

  const isDevpostEvent =
    eventHost &&
    initial.path === '/';


  // DEVPOST RETRIEVAL ADAPTER

  if (isDevpostEvent) {

    // Probe the official rules page

    addCandidate(
      parseLink(initial.base + '/rules'),
      {
        role: 'rules',
        score: 200
      }
    );


    // Probe the official schedule page

    addCandidate(
      parseLink(initial.base + '/details/dates'),
      {
        role: 'dates',
        score: 190
      }
    );

  }


  // RANK ALL DISCOVERED SOURCES

  const ranked = [...candidates.values()]
    .sort((a, b) => b.score - a.score);

  const selected = [];


  // PRIORITIZE SOURCE DIVERSITY

  const roles = isDevpostEvent
    ? ['rules', 'dates']
    : ['rules', 'form', 'dates'];


  for (const role of roles) {

    if (
      selected.length >= MAX_EXTRA
    ) break;

    const best = ranked.find(x =>
      x.role === role &&
      !selected.includes(x)
    );

    if (best) {
      selected.push(best);
    }

  }


  // FILL REMAINING SOURCE SLOTS

  for (const c of ranked) {

    if (
      selected.length >= MAX_EXTRA
    ) break;

    if (!selected.includes(c)) {
      selected.push(c);
    }

  }


  // PREPARE RETRIEVAL ITEMS

  for (const c of selected) {

    arr.push({
      ...arr[0],

      source_id: 'S' + (arr.length + 1),

      url: c.url
    });

  }


  // REPORT SOURCE COVERAGE LIMITS

  if (ranked.length > selected.length) {

    warnings.push(
      `${ranked.length - selected.length} ` +
      'other potentially relevant same-domain ' +
      'pages were not fetched (source limit).'
    );

  }


  if (outside.size) {

    warnings.push(
      'Potentially relevant off-domain pages ' +
      'were not fetched; verify those official ' +
      'links manually.'
    );

  }


  if (!selected.length) {

    warnings.push(
      'No supporting pages discovered. ' +
      'Rules and deadlines may be incomplete.'
    );

  }

}


if (!readable) {

  warnings.push(
    'Landing-page retrieval may be incomplete.'
  );

}


if (warnings.length) {

  arr[0].source_warning =
    warnings.join(' ');

}


return arr.map(x => ({
  json: x
}));

