const sources=[],issues=[];
const first=$('Jina - Read Landing').first().json;
for(let i=0;i<refs.length;i++){
 const s=refs[i]; const r=i===0?first:(responses.find(x=>x.pairedItem?.item===i)?.json||responses[i]?.json||{});
 const status=Number(r.statusCode||(r.error?500:200));
 const full=String(r.data||r.body||'');
 const head=full.slice(0,900);
 if(status>=200&&status<300&&!r.error&&full.length>=240&&!/(?:^|\n)(?:Error:|Warning:.*(?:403|429|blocked)|Title:\s*(?:403|Access Denied|Just a moment|Forbidden|Not Found|404)|403 Forbidden|Access Denied)/i.test(head)){
  const actual=full.match(/^URL Source:\s*(https?:\/\/\S+)/mi)?.[1];
