  out.push({pairedItem:{item:index},json:{owner_id:r.owner_id,opportunity_id:r.opportunity_id,last_reminder_key:marker,reminder_message:`⏰ ${r.title}\nDeadline date: ${r.deadline_date} (${days===0?'today':days+(days===1?' day away':' days away')}). ${r.deadline_time&&r.deadline_timezone?'Published cutoff: '+r.deadline_time+' '+r.deadline_timezone+'.':'Exact closing time is unverified.'}\n\nCore outstanding (${outstanding.length}):\n${lines||'None'}${conditional.length?'\n\nConditional required tasks still unchecked: '+conditional.length+'. Review only those that apply to your chosen path.':''}\n\n/status ${r.opportunity_id}\nVerify the official cutoff time before submitting.`.slice(0,3900)}});
}
return out;

